"""Decode and run the Runaway Confirmation Taker audit.

The workflow emits the readable source to research/runaway_confirmation.py
before execution and commits both the source and generated evidence.
"""
from __future__ import annotations

import base64
import runpy
import zlib
from pathlib import Path

PAYLOAD = ""

source = zlib.decompress(base64.b64decode(PAYLOAD))
path = Path(__file__).with_name("runaway_confirmation.py")
path.write_bytes(source)
runpy.run_path(str(path), run_name="__main__")
